function m5gen(spec){return Array.isArray(spec)?()=>M5[spec[0]](...spec.slice(1)):()=>M5[spec]();}
function m5Lesson(w,d){const G=WEEKS5[w].g;if(G[d]==='*'){const all=G.slice(0,5).flat();return all.map(m5gen);}return G[d].map(m5gen);}
